from collections import deque

def isBipartite(adj,v):
  colour = [-1] * v

  for i in range(v):
    if colour[i]==-1:
      q=deque([i])
      colour[i]=0

      while q:
        curr = q.popleft()
        for j in adj[curr]:
          if colour[j]==-1:
            colour[j]=1-colour[curr]
            q.append(j)
          if colour[j]==colour[curr]:
            return 0
      return 1

# Example 1:

V = 10
adj = [
    [1],        # 0
    [0,2],      # 1
    [1,3,4],    # 2
    [2,5],      # 3
    [2,6],      # 4
    [3,7],      # 5
    [4,7],      # 6
    [5,6,8],    # 7
    [7,9],      # 8
    [8]         # 9
]

print(isBipartite(adj,V))

